/// <summary>
/// The class SysOutgoingEmailTableForm_DIDA_Extension is an extension of the form SysOutgoingEmailTable.
/// </summary>
[ExtensionOf(formStr(SysOutgoingEmailTable))]
final class SysOutgoingEmailTableForm_DIDA_Extension
{
}

Method.Source:
    /// <summary>
    /// Add dynamic button to the form at its initialization.
    /// </summary>
    /// <remarks>
    /// Called by the event handler <c>SysOutgoingEmailTableForm_DIDA_EventHandler.SysOutgoingEmailTable_OnInitialized</c>.
    /// </remarks>
    public void SysOutgoingEmailTable_OnInitialized_DIDA()
    {
        FormMenuButtonControl menuButton = this.design().controlName(formControlStr(SysOutgoingEmailTable, Message_DC)) as FormMenuButtonControl;
        if (menuButton)
        {
            FormButtonControl button = menuButton.addControl(FormControlType::Button, 'DuplicateMessage_DIDA') as FormButtonControl;

            if (button)
            {
                button.text('Duplicate');
                button.helpText('Duplicates the message leaving it in Expired state, so you can update it and Restart send.');
                button.multiSelect(false);
                button.needsRecord(true);
                button.neededPermission(NeededPermission::Create);

                button.registerOverrideMethod(methodStr(FormButtonControl, Clicked), formMethodStr(SysOutgoingEmailTable, DuplicateMessage_DIDA_OnClicked_DIDA), this);
            }
        }
    }

    /// <summary>
    /// Duplicates the selected message leaving it in Expired state, so you can update it and Restart send.
    /// </summary>
    /// <param name = "_sender">The Duplicate button that the user clicked.</param>
    public void DuplicateMessage_DIDA_OnClicked_DIDA(FormButtonControl _sender)
    {
        FormDataSource outgoingEmailDS = _sender.formRun().dataSource(formDataSourceStr(SysOutgoingEmailTable, OutgoingEmail));

        try
        {
            SysOutgoingEmailTable outgoingEmail = outgoingEmailDS.cursor();

            ttsBegin;
            SysOutgoingEmailTable outgoingEmailNew;

            select firstonly outgoingEmailNew where outgoingEmailNew.RecId == outgoingEmail.RecId;

            if (!outgoingEmailNew.RecId)
            {
                throw error('The selected email does not exist anymore. Refresh the form and try again.');
            }

            outgoingEmailNew.EmailItemId = EventInbox::nextEventId();
            outgoingEmailNew.Status = SysEmailStatus::Expired;
            outgoingEmailNew.RetryNum = 0;
            outgoingEmailNew.LastErrorMessage = '';
            outgoingEmailNew.ProcessorID = emptyGuid();
            outgoingEmailNew.SessionId = 0;
            outgoingEmailNew.SessionLoginDateTime = DateTimeUtil::minValue();
            outgoingEmailNew.NextRetryDateTime = DateTimeUtil::minValue();
            outgoingEmailNew.LatestStatusChangeDateTime = DateTimeUtil::getSystemDateTime();
            outgoingEmailNew.UserId = curUserId();
            outgoingEmailNew.insert();

            SysOutgoingEmailData outgoingEmailDataOld, outgoingEmailDataNew;
            while select outgoingEmailDataOld where outgoingEmailDataOld.EmailItemId == outgoingEmail.EmailItemId
            {
                buf2Buf(outgoingEmailDataOld, outgoingEmailDataNew);
                outgoingEmailDataNew.EmailItemId = outgoingEmailNew.EmailItemId;
                outgoingEmailDataNew.insert();
            }

            ttscommit;

            outgoingEmailDS.research(false);
            outgoingEmailDS.positionToRecord(outgoingEmailNew);
        }
        catch
        {
            DocGlobalHelper::handleException(funcName(), 'Error when duplicating the email.');
        }
    }
